","tests_source":"import hashlib,importlib.util,math,os,unittest
P=os.environ.get('CANDIDATE_PATH') or os.environ.get('CANDIDATE_SOURCE_PATH') or 'candidate.py'
if not os.path.isfile(P):
    raise RuntimeError('set CANDIDATE_PATH to the actual candidate source path')
spec=importlib.util.spec_from_file_location('candidate_under_test',P)
mod=importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
RAW=b'root-model-bytes'
def hx(b):
    return hashlib.sha256(b).hexdigest()
MODEL,WORK,SRC,EXE,CTX,CPU=hx(RAW),hx(b'workload'),hx(b'source'),hx(b'exe'),hx(b'context'),hx(b'cpu-ref')
QUANT='q8_0'
VALS={'model_hash':MODEL,'workload_hash':WORK,'source_hash':SRC,'exe_hash':EXE,'context_hash':CTX,'quant':QUANT}
def reg():
    return {'model_hash':RAW,'workload_hash':bytearray(b'workload'),'source_hash':SRC,'exe_hash':EXE,'context_hash':CTX,'cpu_reference_hash':CPU,'artifact_source':'root-store','quant':QUANT}
def dev(i):
    return {'canonical_id':'pci:0000:%02x.0'%i,'physical_alias':'phys:%d'%i,'aliases':['root:%d'%i,'sub:%d:0'%i],'discrete':True,'form_factor':'discrete_gpu'}
def wt(dev,h,n):
    return {'device':dev,'shard_hash':h,'resident_bytes':n,'backing':'device_vram'}
PAIRS=((0.0,0.0),(1.0,1.0625),(2.0,2.0))
def metrics(pairs):
    es=[abs(o-c) for c,o in pairs]
    return math.sqrt(sum(x*x for x in es)/len(es)),max(es)
def att(role,n,ts=1000):
    a={'role':role,'timestamp_ns':ts,'controller':{'args_valid':True,'timeout':False,'policy_cap':False,'native_error':None},'devices':[dev(i) for i in range(n)],'allocator':{'class':'dedicated_vram','fresh':True,'source':'allocd','timestamp_ns':ts}}
    a.update(VALS)
    if role!='four':
        a['execution']={'status':'allocator_oom','requested_bytes':4000}
    else:
        rm,mx=metrics(PAIRS)
        a['execution']={'status':'success','rmse':rm,'max_abs_error':mx,'logits':[{'cpu':c,'observed':o,'tol_abs':0.1} for c,o in PAIRS]}
        a['weights']=[wt('pci:0000:%02x.0'%i,'h%d'%i,1000) for i in range(4)]
        a['allocator']['peak_bytes_by_device']={'pci:0000:%02x.0'%i:1000 for i in range(4)}
    return a
def ev():
    e={'artifact_source':'root-store','cpu_reference_hash':CPU,'observed_at_ns':1000,'model_bytes':4000,'logit_tol_abs':0.1,'attempts':[att('single',1),att('three',3),att('four',4)]}
    e.update(VALS)
    return e
class T(unittest.TestCase):
    def runv(self,e,trusted=None):
        return mod.validate_capacity(e,trusted=reg() if trusted is None else trusted)
    def test_pass(self):
        r=self.runv(ev()); self.assertEqual((r['status'],r['exit_code']),('PASS',0))
    def test_untrusted_bool(self):
        self.assertEqual(mod.validate_capacity(ev(),trusted=True)['errors'],['untrusted'])
    def test_nonhex(self):
        e=ev(); e['model_hash']='not-a-hex'
        for a in e['attempts']: a['model_hash']=e['model_hash']
        self.assertEqual(self.runv(e)['errors'],['hash:model_hash'])
    def test_registry_mismatch(self):
        e=ev(); e['workload_hash']=hx(b'other')
        for a in e['attempts']: a['workload_hash']=e['workload_hash']
        self.assertEqual(self.runv(e)['errors'],['registry_mismatch:workload_hash'])
    def test_missing_registry(self):
        t=reg(); del t['exe_hash']
        self.assertEqual(self.runv(ev(),t)['errors'],['registry:exe_hash'])
    def test_uppercase_hash(self):
        e=ev(); e['context_hash']=CTX.upper()
        for a in e['attempts']: a['context_hash']=e['context_hash']
        t=reg(); t['context_hash']=CTX.upper()
        self.assertEqual(self.runv(e,t)['errors'],['hash:context_hash'])
    def test_three_cards(self):
        e=ev(); e['attempts'][2]['devices']=e['attempts'][2]['devices'][:3]
        self.assertEqual(self.runv(e)['errors'],['four_phys'])
    def test_five_rejected(self):
        e=ev(); e['attempts'][2]['devices'].append(dev(4))
        self.assertEqual(self.runv(e)['errors'],['four_phys'])
    def test_alias_dedup(self):
        e=ev(); e['attempts'][2]['devices'][1]['aliases'].append('root:0')
        self.assertEqual(self.runv(e)['errors'],['dedup:four'])
    def test_repeat_enumeration(self):
        e=ev(); e['attempts'][2]['devices'].append(dev(0))
        self.assertEqual(self.runv(e)['status'],'PASS')
    def test_replicated_weights(self):
        e=ev(); w=e['attempts'][2]['weights']; w[1]['shard_hash']=w[0]['shard_hash']
        self.assertEqual(self.runv(e)['errors'],['replicated_shard'])
    def test_shards_only_device0(self):
        e=ev(); four=e['attempts'][2]; d0=four['devices'][0]['canonical_id']
        for w in four['weights']: w['device']=d0
        four['allocator']['peak_bytes_by_device'][d0]=4000
        self.assertEqual(self.runv(e)['errors'],['shard_coverage'])
    def test_cumulative_peak(self):
        e=ev(); e['attempts'][2]['weights'][:]=[wt('pci:0000:00.0','a',600),wt('pci:0000:00.0','b',600),wt('pci:0000:01.0','c',1000),wt('pci:0000:02.0','d',1000),wt('pci:0000:03.0','e',800)]
        self.assertEqual(self.runv(e)['errors'],['peak_cover'])
    def test_multi_shard_ok(self):
        e=ev(); e['attempts'][2]['weights'][:]=[wt('pci:0000:00.0','a',500),wt('pci:0000:00.0','b',500),wt('pci:0000:01.0','c',1000),wt('pci:0000:02.0','d',1000),wt('pci:0000:03.0','e',1000)]
        self.assertEqual(self.runv(e)['status'],'PASS')
    def test_policy_oom_substitute(self):
        e=ev(); e['attempts'][0]['controller']['policy_cap']=True
        self.assertEqual(self.runv(e)['errors'],['policy:single'])
    def test_missing_peak(self):
        e=ev(); del e['attempts'][2]['allocator']['peak_bytes_by_device']['pci:0000:01.0']
        self.assertEqual(self.runv(e)['status'],'NOT_CHECKED')
    def test_missing_residence(self):
        e=ev(); del e['attempts'][2]['weights'][0]['resident_bytes']
        self.assertEqual(self.runv(e)['status'],'NOT_CHECKED')
    def test_stale(self):
        e=ev(); e['attempts'][2]['timestamp_ns']=999999999999
        self.assertEqual(self.runv(e)['status'],'NOT_CHECKED')
    def test_metrics_contradict(self):
        e=ev(); ex=e['attempts'][2]['execution']; ex['rmse']=0.0; ex['max_abs_error']=0.0
        self.assertEqual(self.runv(e)['errors'],['metric_recompute'])
    def test_full_payload(self):
        e=ev(); ex=e['attempts'][2]['execution']; rm,mx=metrics(PAIRS[:2]); ex['rmse']=rm; ex['max_abs_error']=mx
        self.assertEqual(self.runv(e)['errors'],['metric_recompute'])
    def test_no_1e6_loophole(self):
        e=ev(); ex=e['attempts'][2]['execution']; ex['rmse']=ex['rmse']+1e-6
        self.assertEqual(self.runv(e)['errors'],['metric_recompute'])
    def test_logit_tol_fail(self):
        e=ev(); e['attempts'][2]['execution']['logits'][1]['observed']=1.5
        self.assertEqual(self.runv(e)['errors'],['logit_tol_fail'])
    def test_mismatched_model(self):
        e=ev(); e['attempts'][2]['model_hash']='x'
        self.assertEqual(self.runv(e)['errors'],['bind:four'])
    def test_bool_logit(self):
        e=ev(); e['attempts'][2]['execution']['logits'][0]['observed']=True
        self.assertEqual(self.runv(e)['status'],'NOT_CHECKED')
    def test_huge_logit(self):
        e=ev(); p=e['attempts'][2]['execution']['logits'][0]; p['cpu']=(1<<53)+1; p['observed']=0
        self.assertEqual(self.runv(e)['errors'],['logit_range'])
    def test_igpu(self):
        e=ev(); e['attempts'][2]['devices'][3]['discrete']=False
        self.assertEqual(self.runv(e)['errors'],['discrete:four'])
    def test_host_backing(self):
        e=ev(); e['attempts'][2]['weights'][0]['backing']='host_staged'
        self.assertEqual(self.runv(e)['status'],'NOT_CHECKED')
    def test_shared_allocator(self):
        e=ev(); e['attempts'][2]['allocator']['class']='shared'
        self.assertEqual(self.runv(e)['status'],'NOT_CHECKED')
    def test_reconcile(self):
        e=ev(); e['model_bytes']=4001
        for a in e['attempts']:
            if a['role']!='four': a['execution']['requested_bytes']=4001
        self.assertEqual(self.runv(e)['errors'],['reconcile'])
if __name__=='__main__':
    unittest.main()
","analysis":["RED all_four_shards_only_on_device0: every canonical participant in the four-device attempt must own at least one resident shard. Unique shard-hash count alone is no longer sufficient. One participant may own several unique shards when every participant is covered.","RED sum_of_shards_exceeds_device_peak: resident_bytes are summed per canonical device and that sum must be <= peak_bytes_by_device for the same device. Coverage uses the cumulative resident total.","RED nonhex_artifact_identifiers: model_hash, workload_hash, source_hash, exe_hash, context_hash, and cpu_reference_hash must be exact 64-character lowercase SHA-256. trusted is a caller registry. bytes or bytearray values are hashed with SHA-256; a 64-lowercase string is a caller digest pin. Boolean trusted, a missing key, uppercase hex, and any other pin shape return NOT_CHECKED. A well-formed digest that differs from the registry returns FAIL. artifact_source and quant are exact registry pins and stay matched across the single, three, and four attempts.","RED reported_metrics_contradict_logits: max_abs_error and rmse are recomputed from the full logits payload as max(abs(observed-cpu)) and sqrt(mean of squared errors), using the CPU values as the comparator. Claimed metrics must meet |claimed-recomputed| <= 1e-12 * max(1, |claimed|, |recomputed|). At unit scale the allowance is the original 1e-12 fixed-tolerance contract. Per-logit admission remains abs(observed-cpu) <= tol_abs and abs(tol_abs-logit_tol_abs) <= 1e-12. Claimed rmse must be <= claimed max_abs_error. A 1e-6 absolute drift fails this bound.","Alias dedup is unchanged: overlapping canonical id, physical alias, or alias strings are one physical participant, so a repeated enumeration is one participant and padding does not raise the physical count. Distinct canonical IDs that share an alias fail dedup. Admission counts stay exact: single 1, three 3, four 4.","Single and three require allocator_oom for the same positive model_bytes, with args_valid True, timeout False, and policy_cap False. Four requires execution success, dedicated_vram, fresh allocator provenance, and device_vram shards whose resident bytes sum to model_bytes. Shared, host-staged, or unknown class/backing stays NOT_CHECKED. discrete must be True and form_factor must be discrete_gpu.","Bool is rejected for numeric fields. Integers that are not exact in binary64, non-finite floats, and squared errors that overflow return NOT_CHECKED. The validator reads evidence and does not write it.","Preserved contract: omitted max_staleness_ns still defaults to 10000000000 ns; native_error still accepts None, empty string, or False; non-dict attempts and extraneous roles are still ignored; allocator freshness remains the attempt timestamp window; the 1e-12 tolerance equality remains. A five-participant population fails four_phys. This proposal grants no ROOT_STATIC_ADMISSION."],"prerequisites":["ROOT writes these replacement strings to files itself, sets CANDIDATE_PATH or CANDIDATE_SOURCE_PATH to the source file, and runs the tests under CPython 3 with the standard library. This editor executed nothing and edited no files.","Call validate_capacity(evidence, trusted=registry). Required registry keys are model_hash, workload_hash, source_hash, exe_hash, context_hash, cpu_reference_hash, artifact_source, and quant. Hash keys hold raw artifact bytes or a lowercase SHA-256 pin from the caller trust store. artifact_source and quant hold the exact evidence strings. The registry is caller authority, separate from the evidence document.","Imports are math and hashlib only. Return mapping is PASS exit 0, FAIL exit 1, NOT_CHECKED exit 2. Process bounds, driver calls, allocator measurement, and any real device run remain with ROOT.","The candidate is UNTRUSTED until independent ROOT QA. Original supplied artifacts were left unchanged. Direct HTTP child count for this preparation is 0."],"evidence_limits":["PASS is a GPU-free logic receipt over caller-supplied fields. It is not measured four-card VRAM capacity, not current NVIDIA or AMD numerical qualification, and not P2P or DMA-BUF proof.","Synthetic fixtures, planned budgets, driver memory deltas, advertised capacity, and shared-iGPU arithmetic stay outside dedicated four-discrete admission. The stated host, NVIDIA 5070 Ti plus AMD gfx1036 shared iGPU with no Intel GPU, is context only.","dedicated_vram, device_vram, peaks, resident bytes, aliases, and logit rows are schema fields. The registry binds supplied bytes or digest pins to the named hash fields. cpu_reference_hash is not recomputed from the logit CPU column. shard_hash identity is the exact string, with global uniqueness, and is not a content digest.","Omitted max_staleness_ns still defaults to 10000000000. The allocator timestamp is compared with the attempt, and the attempt with observed_at_ns, so each hop can consume one staleness window. Extraneous roles and non-dict attempt entries are ignored. native_error None, empty string, and False remain accepted sentinels.","Devices with disjoint declared alias sets count as distinct participants. This module has no hardware enumerator. A transitive alias bridge that ties distinct canonical IDs together fails closed because the canonical count and the physical count disagree. A direct cross-device alias collision fails dedup.","Admission requires exactly four physical discrete participants, one-card and three-card allocator OOM, and four-card numerical success on the same model, workload, source, executable, context, and quant tuple. Missing authority or an unknown memory class is NOT_CHECKED. A PASS authorizes no purchase, BIOS change, driver change, or GPU action."],"references":["Untrusted source 7005c1fc83a4a9901e30cf8e705dbe5961dc1010c645e963bb08ec75a7808267","Untrusted tests aae6be310522f4d7a3152652ffd2816df186db72a317f5ead1372ec9dda95239","Spec 8ab81aa30e7ccd104b2e8ae6fbb9d19c87b31fffb7fcb32880dc97f0c02d1bb8","Muse review de2b5a98c4ad598c69db85e9a9